BEGIN
    EXECUTE IMMEDIATE 'GRANT EXECUTE ON DBMS_CLOUD TO {0}';
    EXECUTE IMMEDIATE 'GRANT EXECUTE ON DBMS_CLOUD_AI TO {0}';
END;

BEGIN
    DBMS_VECTOR.LOAD_ONNX_MODEL_CLOUD(
        model_name => {#0},
        credential => {#1},
        uri        => {#2});
END;

begin
    DBMS_VECTOR.DROP_ONNX_MODEL(
            model_name => {#0});
end;

BEGIN
    EXECUTE IMMEDIATE '
        CREATE TABLE IF NOT EXISTS {0} (
            id         VARCHAR(4000) PRIMARY KEY,
            embedding  VECTOR(*, FLOAT32) NOT NULL,
            text CLOB,
            metadata JSON
        )
    ';
END;

BEGIN
    EXECUTE IMMEDIATE '
        CREATE TABLE IF NOT EXISTS {0} (
            id       varchar(50) not null,
            b_lob    blob ,
            metadata JSON
        ) LOB(b_lob) STORE AS SECUREFILE (NOCACHE FILESYSTEM_LIKE_LOGGING)
    ';
END;

INSERT INTO {0}
(id, b_lob, metadata)
VALUES ({#1}, EMPTY_BLOB(), {#2})

UPDATE {0}
SET b_lob = {#1}
WHERE id = {#2}

DECLARE
    v_doc BLOB;
BEGIN
    SELECT b_lob INTO v_doc FROM {1} WHERE id = {#2};

    INSERT INTO {0} (id, {3}, {4}, {5})
        SELECT
            SYS_GUID(),
            jt.embed_data,
            TO_VECTOR(jt.embed_vector),
            JSON_MERGEPATCH(
                {#8},
                JSON_OBJECT(
                    KEY 'chunk_id'
                    VALUE JSON_VALUE(t.COLUMN_VALUE, '$.embed_id' RETURNING VARCHAR2(50))
                ) RETURNING CLOB
            )
        FROM TABLE(
            DBMS_VECTOR_CHAIN.UTL_TO_EMBEDDINGS(
                DBMS_VECTOR_CHAIN.UTL_TO_CHUNKS(
                    DBMS_VECTOR_CHAIN.UTL_TO_TEXT(v_doc, json(json_object('plaintext' VALUE true))),
                    json({#6})
                ),
                json({#7})
            )
        ) t,
        JSON_TABLE(
            t.COLUMN_VALUE, '$'
                COLUMNS (
                    embed_data   CLOB PATH '$.embed_data',
                    embed_vector CLOB PATH '$.embed_vector'
                )
        ) jt;
END;

BEGIN
    DBMS_VECTOR.LOAD_ONNX_MODEL({#0}, {#1});
END;

select
    CHUNK_OFFSET as "Chunk offset",
    CHUNK_LENGTH as "Chunk length",
    CHUNK_TEXT as "Chunk text"
from VECTOR_CHUNKS(
    {#0}
    BY {1}
    MAX {2}
    OVERLAP {3}
    SPLIT BY {4})
